import{_ as a,o as s,c as i,aj as t}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Setting up the local environment and workspace","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/cli/setup-local.md","filePath":"en/tools/cli/setup-local.md"}'),n={name:"en/tools/cli/setup-local.md"};function l(o,e,r,p,h,d){return s(),i("div",null,e[0]||(e[0]=[t(`<h1 id="setting-up-the-local-environment-and-workspace" tabindex="-1">Setting up the local environment and workspace <a class="header-anchor" href="#setting-up-the-local-environment-and-workspace" aria-label="Permalink to &quot;Setting up the local environment and workspace&quot;">​</a></h1><p>This guide explains how to set up your environment for Angular development using the <a href="/en/cli" title="CLI command reference">Angular CLI</a>. It includes information about installing the CLI, creating an initial workspace and starter app, and running that app locally to verify your setup.</p><div class="tip custom-block"><p class="custom-block-title">Try Angular without local setup</p><p>If you are new to Angular, you might want to start with <a href="/en/tutorials/learn-angular">Try it now!</a>, which introduces the essentials of Angular in your browser. This standalone tutorial takes advantage of the interactive <a href="https://stackblitz.com" target="_blank" rel="noreferrer">StackBlitz</a> environment for online development. You don&#39;t need to set up your local environment until you&#39;re ready.</p></div><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>To use Angular CLI, you should be familiar with the following:</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript" target="_blank" rel="noreferrer">JavaScript</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTML" target="_blank" rel="noreferrer">HTML</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/CSS" target="_blank" rel="noreferrer">CSS</a></li></ul><p>You should also be familiar with usage of command line interface (CLI) tools and have a general understanding of command shells. Knowledge of <a href="https://www.typescriptlang.org" target="_blank" rel="noreferrer">TypeScript</a> is helpful, but not required.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>To install Angular CLI on your local system, you need to install <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a>. Angular CLI uses Node and its associated package manager, npm, to install and run JavaScript tools outside the browser.</p><p><a href="https://nodejs.org/en/download" target="_blank" rel="noreferrer">Download and install Node.js</a>, which will include the <code>npm</code> CLI as well. Angular requires an <a href="https://nodejs.org/en/about/previous-releases" target="_blank" rel="noreferrer">active LTS or maintenance LTS</a> version of Node.js. See <a href="/en/reference/versions">Angular&#39;s version compatibility</a> guide for more information.</p><h2 id="install-the-angular-cli" tabindex="-1">Install the Angular CLI <a class="header-anchor" href="#install-the-angular-cli" aria-label="Permalink to &quot;Install the Angular CLI&quot;">​</a></h2><p>To install the Angular CLI, open a terminal window and run the following command:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-QHkEk" id="tab-JGcfYZO" checked><label data-title="npm" for="tab-JGcfYZO">npm</label><input type="radio" name="group-QHkEk" id="tab-jDSJwk1"><label data-title="pnpm" for="tab-jDSJwk1">pnpm</label><input type="radio" name="group-QHkEk" id="tab-Xo2guaB"><label data-title="yarn" for="tab-Xo2guaB">yarn</label><input type="radio" name="group-QHkEk" id="tab-34CzhVI"><label data-title="bun" for="tab-34CzhVI">bun</label></div><div class="blocks"><div class="language-shell vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div></div></div><h3 id="powershell-execution-policy" tabindex="-1">Powershell execution policy <a class="header-anchor" href="#powershell-execution-policy" aria-label="Permalink to &quot;Powershell execution policy&quot;">​</a></h3><p>On Windows client computers, the execution of PowerShell scripts is disabled by default, so the above command may fail with an error. To allow the execution of PowerShell scripts, which is needed for npm global binaries, you must set the following <a href="https://docs.microsoft.com/powershell/module/microsoft.powershell.core/about/about_execution_policies" target="_blank">execution policy</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Set-ExecutionPolicy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CurrentUser</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ExecutionPolicy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RemoteSigned</span></span></code></pre></div><p>Carefully read the message displayed after executing the command and follow the instructions. Make sure you understand the implications of setting an execution policy.</p><h3 id="unix-permissions" tabindex="-1">Unix permissions <a class="header-anchor" href="#unix-permissions" aria-label="Permalink to &quot;Unix permissions&quot;">​</a></h3><p>On some Unix-like setups, global scripts may be owned by the root user, so to the above command may fail with a permission error. Run with <code>sudo</code> to execute the command as the root user and enter your password when prompted:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-e5slH" id="tab-fxmS2A3" checked><label data-title="npm" for="tab-fxmS2A3">npm</label><input type="radio" name="group-e5slH" id="tab-jQHd1RE"><label data-title="pnpm" for="tab-jQHd1RE">pnpm</label><input type="radio" name="group-e5slH" id="tab-uaFk4sV"><label data-title="yarn" for="tab-uaFk4sV">yarn</label><input type="radio" name="group-e5slH" id="tab--3P5Do2"><label data-title="bun" for="tab--3P5Do2">bun</label></div><div class="blocks"><div class="language-shell vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div></div></div><p>Make sure you understand the implications of running commands as root.</p><h2 id="create-a-workspace-and-initial-application" tabindex="-1">Create a workspace and initial application <a class="header-anchor" href="#create-a-workspace-and-initial-application" aria-label="Permalink to &quot;Create a workspace and initial application&quot;">​</a></h2><p>You develop apps in the context of an Angular <strong>workspace</strong>.</p><p>To create a new workspace and initial starter app, run the CLI command <code>ng new</code> and provide the name <code>my-app</code>, as shown here, then answer prompts about features to include:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The Angular CLI installs the necessary Angular npm packages and other dependencies. This can take a few minutes.</p><p>The CLI creates a new workspace and a small welcome app in a new directory with the same name as the workspace, ready to run. Navigate to the new directory so subsequent commands use this workspace.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><h2 id="run-the-application" tabindex="-1">Run the application <a class="header-anchor" href="#run-the-application" aria-label="Permalink to &quot;Run the application&quot;">​</a></h2><p>The Angular CLI includes a development server, for you to build and serve your app locally. Run the following command:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --open</span></span></code></pre></div><p>The <code>ng serve</code> command launches the server, watches your files, as well as rebuilds the app and reloads the browser as you make changes to those files.</p><p>The <code>--open</code> (or just <code>-o</code>) option automatically opens your browser to <code>http://localhost:4200/</code> to view the generated application.</p><h2 id="workspaces-and-project-files" tabindex="-1">Workspaces and project files <a class="header-anchor" href="#workspaces-and-project-files" aria-label="Permalink to &quot;Workspaces and project files&quot;">​</a></h2><p>The <a href="https://angular.dev/cli/new" target="_blank" rel="noreferrer"><code>ng new</code></a> command creates an <a href="/en/reference/configs/workspace-config">Angular workspace</a> folder and generates a new application inside it. A workspace can contain multiple applications and libraries. The initial application created by the <a href="https://angular.dev/cli/new" target="_blank" rel="noreferrer"><code>ng new</code></a> command is at the root directory of the workspace. When you generate an additional application or library in an existing workspace, it goes into a <code>projects/</code> subfolder by default.</p><p>A newly generated application contains the source files for a root component and template. Each application has a <code>src</code> folder that contains its components, data, and assets.</p><p>You can edit the generated files directly, or add to and modify them using CLI commands. Use the <a href="https://angular.dev/cli/generate" target="_blank" rel="noreferrer"><code>ng generate</code></a> command to add new files for additional components, directives, pipes, services, and more. Commands such as <a href="https://angular.dev/cli/add" target="_blank" rel="noreferrer"><code>ng add</code></a> and <a href="https://angular.dev/cli/generate" target="_blank" rel="noreferrer"><code>ng generate</code></a>, which create or operate on applications and libraries, must be executed from within a workspace. By contrast, commands such as <code>ng new</code> must be executed <em>outside</em> a workspace because they will create a new one.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><p>Learn more about the <a href="/en/reference/configs/file-structure">file structure</a> and <a href="/en/reference/configs/workspace-config">configuration</a> of the generated workspace.</p></li><li><p>Test your new application with <a href="https://angular.dev/cli/test" target="_blank" rel="noreferrer"><code>ng test</code></a>.</p></li><li><p>Generate boilerplate like components, directives, and pipes with <a href="https://angular.dev/cli/generate" target="_blank" rel="noreferrer"><code>ng generate</code></a>.</p></li><li><p>Deploy your new application and make it available to real users with <a href="https://angular.dev/cli/deploy" target="_blank" rel="noreferrer"><code>ng deploy</code></a>.</p></li><li><p>Set up and run end-to-end tests of your application with <a href="https://angular.dev/cli/e2e" target="_blank" rel="noreferrer"><code>ng e2e</code></a>.</p></li></ul>`,39)]))}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
